//! Replays `fixtures/reference/math_goals.json`, generated by `tools/refgen/run.sh` from the
//! real upstream classes running against the real Minecraft client. Floating point values are
//! compared bit for bit (any NaN matches any NaN).

// Upstream runs on Java Edition, with its costs.
#![cfg(not(feature = "bedrock"))]

use std::sync::{Arc, LazyLock};

use baritone::api::pathing::goals::{
    Goal, GoalAxis, GoalBlock, GoalComposite, GoalGetToBlock, GoalInverted, GoalNear, GoalRunAway,
    GoalStrictDirection, GoalTwoBlocks, GoalXZ, GoalYLevel,
};
use baritone::api::pathing::movement::{ActionCosts, COST_INF, action_costs};
use baritone::api::utils::{BetterBlockPos, Rotation, rotation_utils};
use baritone::mc::{Direction, Vec3, mth};
use baritone::utils::baritone_math;
use serde_json::Value;

static FIXTURE: LazyLock<Value> = LazyLock::new(|| {
    serde_json::from_str(include_str!("fixtures/reference/math_goals.json")).unwrap()
});

fn section(name: &str) -> &'static Value {
    &FIXTURE[name]
}

fn rows(section_name: &str, key: &str) -> &'static [Value] {
    let rows = section(section_name)[key]
        .as_array()
        .unwrap_or_else(|| panic!("missing {section_name}.{key}"));
    assert!(!rows.is_empty(), "{section_name}.{key} is empty");
    rows
}

fn int(v: &Value) -> i32 {
    i32::try_from(v.as_i64().unwrap()).unwrap()
}

fn long(v: &Value) -> i64 {
    v.as_i64().unwrap()
}

fn dbl(v: &Value) -> f64 {
    f64::from_bits(v.as_i64().unwrap() as u64)
}

fn flt(v: &Value) -> f32 {
    f32::from_bits(int(v) as u32)
}

fn boolean(v: &Value) -> bool {
    v.as_bool().unwrap()
}

#[track_caller]
fn assert_f64(actual: f64, expected: f64, context: &dyn std::fmt::Debug) {
    if expected.is_nan() {
        assert!(actual.is_nan(), "{context:?}: expected NaN, got {actual}");
    } else {
        assert_eq!(
            actual.to_bits(),
            expected.to_bits(),
            "{context:?}: expected {expected:e}, got {actual:e}"
        );
    }
}

#[track_caller]
fn assert_f32(actual: f32, expected: f32, context: &dyn std::fmt::Debug) {
    if expected.is_nan() {
        assert!(actual.is_nan(), "{context:?}: expected NaN, got {actual}");
    } else {
        assert_eq!(
            actual.to_bits(),
            expected.to_bits(),
            "{context:?}: expected {expected:e}, got {actual:e}"
        );
    }
}

fn pos(r: &[Value], at: usize) -> BetterBlockPos {
    BetterBlockPos::new(int(&r[at]), int(&r[at + 1]), int(&r[at + 2]))
}

#[test]
fn fixture_is_for_pinned_upstream() {
    let upstream = include_str!("../UPSTREAM").trim();
    assert_eq!(
        FIXTURE["upstream"].as_str().unwrap(),
        upstream,
        "regenerate with tools/refgen/run.sh"
    );
}

// region BetterBlockPos

#[test]
fn better_block_pos_hash() {
    for r in rows("better_block_pos", "hash") {
        let r = r.as_array().unwrap();
        let p = pos(r, 0);
        assert_eq!(
            BetterBlockPos::long_hash(p.x, p.y, p.z),
            long(&r[3]),
            "{p:?}"
        );
        assert_eq!(BetterBlockPos::long_hash_pos(p), long(&r[3]), "{p:?}");
        assert_eq!(p.hash_code(), int(&r[4]), "{p:?}");
    }
}

#[test]
fn better_block_pos_serialize() {
    for r in rows("better_block_pos", "serialize") {
        let r = r.as_array().unwrap();
        let p = pos(r, 0);
        let serialized = BetterBlockPos::serialize_to_long(p.x, p.y, p.z);
        assert_eq!(serialized, long(&r[3]), "{p:?}");
        assert_eq!(
            BetterBlockPos::deserialize_from_long(serialized),
            pos(r, 4),
            "{p:?}"
        );
    }
    for r in rows("better_block_pos", "deserialize") {
        let r = r.as_array().unwrap();
        assert_eq!(
            BetterBlockPos::deserialize_from_long(long(&r[0])),
            pos(r, 1),
            "{}",
            long(&r[0])
        );
    }
}

#[test]
fn better_block_pos_from_f64() {
    for r in rows("better_block_pos", "from_double") {
        let r = r.as_array().unwrap();
        let (x, y, z) = (dbl(&r[0]), dbl(&r[1]), dbl(&r[2]));
        assert_eq!(BetterBlockPos::from_f64(x, y, z), pos(r, 3), "{x} {y} {z}");
    }
}

#[test]
fn better_block_pos_distance() {
    for r in rows("better_block_pos", "distance") {
        let r = r.as_array().unwrap();
        let (a, b) = (pos(r, 0), pos(r, 3));
        assert_f64(a.distance_sq(&b), dbl(&r[6]), &(a, b));
        assert_f64(a.distance_to(&b), dbl(&r[7]), &(a, b));
    }
}

#[test]
fn better_block_pos_offsets() {
    for r in rows("better_block_pos", "offsets") {
        let r = r.as_array().unwrap();
        let p = pos(r, 0);
        let amt = int(&r[3]);
        let mut actual = vec![
            p.above_n(amt),
            p.below_n(amt),
            p.north_n(amt),
            p.south_n(amt),
            p.east_n(amt),
            p.west_n(amt),
        ];
        actual.extend(Direction::VALUES.map(|d| p.relative_n(d, amt)));
        for (i, q) in actual.into_iter().enumerate() {
            assert_eq!(q, pos(r, 4 + i * 3), "{p:?} amt={amt} op={i}");
        }
    }
    for r in rows("better_block_pos", "unit_offsets") {
        let r = r.as_array().unwrap();
        let p = pos(r, 0);
        let mut actual = vec![
            p.above(),
            p.below(),
            p.north(),
            p.south(),
            p.east(),
            p.west(),
        ];
        actual.extend(Direction::VALUES.map(|d| p.relative(d)));
        for (i, q) in actual.into_iter().enumerate() {
            assert_eq!(q, pos(r, 3 + i * 3), "{p:?} op={i}");
        }
    }
}

#[test]
fn better_block_pos_to_string() {
    for r in rows("better_block_pos", "to_string") {
        let r = r.as_array().unwrap();
        assert_eq!(pos(r, 0).to_string(), r[3].as_str().unwrap());
    }
}

