// region Mth

#[test]
fn mth_tables() {
    let mth_section = section("mth");
    let table = mth::sin_table();
    assert_eq!(
        table.len() as i64,
        mth_section["sin_table_len"].as_i64().unwrap()
    );
    let mut h: u64 = 0xcbf29ce484222325;
    for v in table.iter() {
        h ^= v.to_bits() as u64;
        h = h.wrapping_mul(0x100000001b3);
    }
    for r in rows("mth", "sin_table_samples") {
        let r = r.as_array().unwrap();
        let i = int(&r[0]) as usize;
        assert_f32(table[i], flt(&r[1]), &i);
    }
    assert_eq!(
        h as i64,
        mth_section["sin_table_fnv"].as_i64().unwrap(),
        "SIN table differs"
    );

    for (i, v) in rows("mth", "asin_tab").iter().enumerate() {
        assert_f64(mth::asin_tab()[i], dbl(v), &("ASIN_TAB", i));
    }
    for (i, v) in rows("mth", "cos_tab").iter().enumerate() {
        assert_f64(mth::cos_tab()[i], dbl(v), &("COS_TAB", i));
    }
    assert_f64(
        mth::frac_bias(),
        dbl(&mth_section["frac_bias"]),
        &"FRAC_BIAS",
    );
}

