// region ActionCosts, BaritoneMath

#[test]
fn action_costs_constants() {
    let s = section("action_costs");
    let c = ActionCosts::java();
    let expected = [
        ("WALK_ONE_BLOCK_COST", c.walk_one_block_cost),
        ("WALK_ONE_IN_WATER_COST", c.walk_one_in_water_cost),
        (
            "WALK_ONE_OVER_SOUL_SAND_COST",
            c.walk_one_over_soul_sand_cost,
        ),
        ("LADDER_UP_ONE_COST", c.ladder_up_one_cost),
        ("LADDER_DOWN_ONE_COST", c.ladder_down_one_cost),
        ("SNEAK_ONE_BLOCK_COST", c.sneak_one_block_cost),
        ("SPRINT_ONE_BLOCK_COST", c.sprint_one_block_cost),
        ("SPRINT_MULTIPLIER", c.sprint_multiplier),
        ("WALK_OFF_BLOCK_COST", c.walk_off_block_cost),
        ("CENTER_AFTER_FALL_COST", c.center_after_fall_cost),
        ("COST_INF", COST_INF),
        ("FALL_1_25_BLOCKS_COST", c.fall_1_25_blocks_cost),
        ("FALL_0_25_BLOCKS_COST", c.fall_0_25_blocks_cost),
        ("JUMP_ONE_BLOCK_COST", c.jump_one_block_cost),
    ];
    for (name, actual) in expected {
        assert_f64(actual, dbl(&s[name]), &name);
    }
    let fall = rows("action_costs", "FALL_N_BLOCKS_COST");
    assert_eq!(c.fall_n_blocks_cost.len(), fall.len());
    for (i, v) in fall.iter().enumerate() {
        assert_f64(c.fall_n_blocks_cost[i], dbl(v), &("FALL_N_BLOCKS_COST", i));
    }
    assert_eq!(
        **action_costs(),
        c,
        "default active costs are the Java costs"
    );
}

