// region Rotation, RotationUtils

#[test]
fn rotation_statics() {
    for r in rows("rotation", "normalize_clamp") {
        let r = r.as_array().unwrap();
        let v = flt(&r[0]);
        assert_f32(Rotation::normalize_yaw(v), flt(&r[1]), &("normalizeYaw", v));
        assert_f32(Rotation::clamp_pitch(v), flt(&r[2]), &("clampPitch", v));
    }
    for r in rows("rotation", "yaw_distance_from_offset") {
        let r = r.as_array().unwrap();
        let (a, b) = (flt(&r[0]), flt(&r[1]));
        assert_f32(
            Rotation::yaw_distance_from_offset(a, b),
            flt(&r[2]),
            &(a, b),
        );
    }
}

#[test]
fn rotation_pairs() {
    for r in rows("rotation", "pairs") {
        let r = r.as_array().unwrap();
        let a = Rotation::new(flt(&r[0]), flt(&r[1]));
        let b = Rotation::new(flt(&r[2]), flt(&r[3]));
        let ctx = (a, b);
        let add = a.add(&b);
        assert_f32(add.get_yaw(), flt(&r[4]), &ctx);
        assert_f32(add.get_pitch(), flt(&r[5]), &ctx);
        let sub = a.subtract(&b);
        assert_f32(sub.get_yaw(), flt(&r[6]), &ctx);
        assert_f32(sub.get_pitch(), flt(&r[7]), &ctx);
        let nc = a.normalize_and_clamp();
        assert_f32(nc.get_yaw(), flt(&r[8]), &ctx);
        assert_f32(nc.get_pitch(), flt(&r[9]), &ctx);
        assert_eq!(a.is_really_close_to(&b), boolean(&r[10]), "{ctx:?}");
        assert_eq!(a.yaw_is_really_close(&b), boolean(&r[11]), "{ctx:?}");
    }
}

fn vec3(r: &[Value], at: usize) -> Vec3 {
    Vec3::new(dbl(&r[at]), dbl(&r[at + 1]), dbl(&r[at + 2]))
}

#[test]
fn rotation_utils_calc_rotation() {
    for r in rows("rotation_utils", "calc_rotation_from_vec3d") {
        let r = r.as_array().unwrap();
        let (orig, dest) = (vec3(r, 0), vec3(r, 3));
        let current = Rotation::new(flt(&r[6]), flt(&r[7]));
        let ctx = (orig, dest, current);
        let plain = rotation_utils::calc_rotation_from_vec3d_absolute(orig, dest);
        assert_f32(plain.get_yaw(), flt(&r[8]), &ctx);
        assert_f32(plain.get_pitch(), flt(&r[9]), &ctx);
        let relative = rotation_utils::calc_rotation_from_vec3d(orig, dest, current);
        assert_f32(relative.get_yaw(), flt(&r[10]), &ctx);
        assert_f32(relative.get_pitch(), flt(&r[11]), &ctx);
    }
    for r in rows("rotation_utils", "calc_rotation_from_coords") {
        let r = r.as_array().unwrap();
        let (orig, dest) = (pos(r, 0), pos(r, 3));
        let rotation = rotation_utils::calc_rotation_from_coords(orig, dest);
        assert_f32(rotation.get_yaw(), flt(&r[6]), &(orig, dest));
        assert_f32(rotation.get_pitch(), flt(&r[7]), &(orig, dest));
    }
}

#[test]
fn rotation_utils_look_direction() {
    for r in rows("rotation_utils", "calc_look_direction_from_rotation") {
        let r = r.as_array().unwrap();
        let rotation = Rotation::new(flt(&r[0]), flt(&r[1]));
        let v = rotation_utils::calc_look_direction_from_rotation(rotation);
        assert_f64(v.x, dbl(&r[2]), &rotation);
        assert_f64(v.y, dbl(&r[3]), &rotation);
        assert_f64(v.z, dbl(&r[4]), &rotation);
    }
}

