// region goals

fn build_goal(spec: &Value) -> Arc<dyn Goal> {
    let i = |key: &str| int(&spec[key]);
    let p = || BetterBlockPos::new(i("x"), i("y"), i("z"));
    match spec["kind"].as_str().unwrap() {
        "GoalBlock" => Arc::new(GoalBlock::new(i("x"), i("y"), i("z"))),
        "GoalTwoBlocks" => Arc::new(GoalTwoBlocks::new(i("x"), i("y"), i("z"))),
        "GoalGetToBlock" => Arc::new(GoalGetToBlock::new(p())),
        "GoalNear" => Arc::new(GoalNear::new(p(), i("range"))),
        "GoalXZ" => Arc::new(GoalXZ::new(i("x"), i("z"))),
        "GoalYLevel" => Arc::new(GoalYLevel::new(i("level"))),
        "GoalAxis" => Arc::new(GoalAxis::new()),
        "GoalStrictDirection" => Arc::new(GoalStrictDirection::new(
            p(),
            Direction::by_name(spec["direction"].as_str().unwrap()).unwrap(),
        )),
        "GoalRunAway" => {
            let from = spec["from"]
                .as_array()
                .unwrap()
                .iter()
                .map(|r| pos(r.as_array().unwrap(), 0))
                .collect();
            let maintain_y = spec["maintain_y"].as_i64().map(|v| v as i32);
            Arc::new(GoalRunAway::new(dbl(&spec["distance"]), maintain_y, from))
        }
        "GoalComposite" => Arc::new(GoalComposite::new(
            spec["goals"]
                .as_array()
                .unwrap()
                .iter()
                .map(build_goal)
                .collect(),
        )),
        "GoalInverted" => Arc::new(GoalInverted::new(build_goal(&spec["origin"]))),
        kind => panic!("unknown goal kind {kind}"),
    }
}

#[test]
fn goals() {
    let cases = FIXTURE["goals"].as_array().unwrap();
    assert!(!cases.is_empty());
    for case in cases {
        let goal = build_goal(&case["spec"]);
        assert_eq!(goal.to_string(), case["to_string"].as_str().unwrap());
        assert_f64(
            goal.heuristic_at_goal(),
            dbl(&case["heuristic_at_goal"]),
            &goal,
        );
        for r in case["samples"].as_array().unwrap() {
            let r = r.as_array().unwrap();
            let p = pos(r, 0);
            assert_eq!(
                goal.is_in_goal(p.x, p.y, p.z),
                boolean(&r[3]),
                "{goal} at {p:?}"
            );
            assert_eq!(goal.is_in_goal_pos(p), boolean(&r[3]), "{goal} at {p:?}");
            assert_f64(
                goal.heuristic(p.x, p.y, p.z),
                dbl(&r[4]),
                &(goal.to_string(), p),
            );
            assert_f64(goal.heuristic_pos(p), dbl(&r[4]), &(goal.to_string(), p));
        }
    }
}

#[test]
fn goal_statics() {
    for r in rows("goal_statics", "goal_block_calculate") {
        let r = r.as_array().unwrap();
        let (x, y, z) = (dbl(&r[0]), int(&r[1]), dbl(&r[2]));
        assert_f64(GoalBlock::calculate(x, y, z), dbl(&r[3]), &(x, y, z));
    }
    for r in rows("goal_statics", "goal_xz_calculate") {
        let r = r.as_array().unwrap();
        let (x, z) = (dbl(&r[0]), dbl(&r[1]));
        assert_f64(GoalXZ::calculate(x, z), dbl(&r[2]), &(x, z));
    }
    for r in rows("goal_statics", "goal_y_level_calculate") {
        let r = r.as_array().unwrap();
        let (goal_y, current_y) = (int(&r[0]), int(&r[1]));
        assert_f64(
            GoalYLevel::calculate(goal_y, current_y),
            dbl(&r[2]),
            &(goal_y, current_y),
        );
    }
    for r in rows("goal_statics", "goal_xz_from_direction") {
        let r = r.as_array().unwrap();
        let (origin, yaw, distance) = (vec3(r, 0), flt(&r[3]), dbl(&r[4]));
        let goal = GoalXZ::from_direction(origin, yaw, distance);
        assert_eq!(
            (goal.get_x(), goal.get_z()),
            (int(&r[5]), int(&r[6])),
            "{origin:?} {yaw} {distance}"
        );
    }
}

